examples.template:
CompositionLocalProvider(LocalConfiguration provides locale) {
    MonarchStackedProportionBar(
        label = {{label}},
        segments = listOf(
            MonarchStackedProportionBarSegment({{segments.0.key}}, {{segments.0.label}}, {{segments.0.value|double}}),
            MonarchStackedProportionBarSegment({{segments.1.key}}, {{segments.1.label}}, {{segments.1.value|double}}),
            MonarchStackedProportionBarSegment({{segments.2.key}}, {{segments.2.label}}, {{segments.2.value|double}}),
            MonarchStackedProportionBarSegment({{segments.3.key}}, {{segments.3.label}}, {{segments.3.value|double}}),
            MonarchStackedProportionBarSegment({{segments.4.key}}, {{segments.4.label}}, {{segments.4.value|double}}),
        ),
        modifier = Modifier.widthIn(max = 512.dp),
    )
}

examples.setupTemplate:
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag({{locale}})) }
}

examples.setup:
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag("en-US")) }
}

